#include "csv_writer.h"
#include <stdio.h>
int write_results_csv_file(const char*path,const SimulationResult*s,const EstimateSample*e,size_t en){FILE*f=fopen(path,"w");if(!f)return -1;fprintf(f,"t,true_x,true_y,true_vx,true_vy,gps_valid,gps_x,gps_y,est_x,est_y,est_vx,est_vy,est_pos_std,used_gps\n");size_t gi=0,ei=0;for(size_t i=0;i<s->truth_count;i++){TruthSample*t=&s->truth[i];fprintf(f,"%.3f,%.3f,%.3f,%.3f,%.3f,",t->t,t->pos.x,t->pos.y,t->vel.x,t->vel.y);while(gi<s->gps_count&&s->gps[gi].step<t->step)gi++;if(gi<s->gps_count&&s->gps[gi].step==t->step){GpsMeasurement*g=&s->gps[gi];if(g->valid)fprintf(f,"1,%.3f,%.3f,",g->pos.x,g->pos.y);else fprintf(f,"0,,," );}else fprintf(f,",,,");while(ei<en&&e[ei].step<t->step)ei++;if(ei<en&&e[ei].step==t->step){EstimateSample*x=&e[ei];fprintf(f,"%.3f,%.3f,%.3f,%.3f,%.3f,%d",x->pos.x,x->pos.y,x->vel.x,x->vel.y,x->pos_std,x->used_gps);}else fprintf(f,",,,,,");fputc('\n',f);}int ok=ferror(f);fclose(f);return ok?-1:0;}
